// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.file.Path;

import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.evaluation.NativeCancellationTestAccess;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelQueryCancelledException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

/** Metadata-backed exact counts retain cancellation and describe their bounded native work accurately. */
class LmdbPersistentAdjacencyCountTest {

	@TempDir
	Path directory;

	@ParameterizedTest
	@CsvSource({ "0,4", "2,3", "3,2", "6,2", "8,3" })
	void preparedCountQuotesOneMetadataDescentAndDoesNotScanStatements(int mask, long expected) throws Exception {
		try (TripleStore store = seededStore(); Txn snapshot = store.getTxnManager().createReadTxn()) {
			long subject = (mask & 1) == 0 ? -1 : 10;
			long predicate = (mask & 2) == 0 ? -1 : 20;
			long object = (mask & 4) == 0 ? -1 : 30;
			long context = (mask & 8) == 0 ? -1 : 7;
			TripleStore.PreparedIndexCount count = store.prepareExactIndexCount(snapshot,
					subject, predicate, object, context, true);
			assertThat(count).isNotNull();
			assertThat(count.lowPageReads()).isGreaterThanOrEqualTo(1D);
			assertThat(count.highPageReads()).as("one metadata key has one root-to-leaf descent")
					.isEqualTo(count.lowPageReads());
			try (LmdbStartupReadCounter reads = new LmdbStartupReadCounter()) {
				assertThat(count.execute()).hasValue(expected);
				assertThat(reads.operations().getOrDefault("mdb_get", 0L)).isEqualTo(1L);
				assertThat(reads.operations().getOrDefault("mdb_cursor_get", 0L)).isZero();
				assertThat(reads.operations().getOrDefault("mdb_cursor_open", 0L)).isZero();
			}
		}
	}

	@Test
	void cancelledPreparedCountDoesNotReadMetadataAndRemainsUsable() throws Exception {
		try (TripleStore store = seededStore(); Txn snapshot = store.getTxnManager().createReadTxn()) {
			TripleStore.PreparedIndexCount count = store.prepareExactIndexCount(snapshot, -1, 20, -1, -1, true);
			assertThat(count).isNotNull();
			try (LmdbStartupReadCounter reads = new LmdbStartupReadCounter()) {
				assertThrows(KernelQueryCancelledException.class,
						() -> NativeCancellationTestAccess.withCancelledNativeToken(count::execute));
				assertThat(reads.operations().getOrDefault("mdb_get", 0L)).isZero();
			}
			assertThat(count.execute()).hasValue(3L);
		}
	}

	@Test
	void cancelledDirectCountDoesNotReadMetadataAndKeepsTheSnapshotUsable() throws Exception {
		try (TripleStore store = seededStore(); Txn snapshot = store.getTxnManager().createReadTxn()) {
			try (LmdbStartupReadCounter reads = new LmdbStartupReadCounter()) {
				assertThrows(KernelQueryCancelledException.class,
						() -> NativeCancellationTestAccess.withCancelledNativeToken(
								() -> store.countTriples(snapshot, -1, 20, -1, -1, true)));
				assertThat(reads.operations().getOrDefault("mdb_get", 0L)).isZero();
			}
			assertThat(store.countTriples(snapshot, -1, 20, -1, -1, true)).isEqualTo(3L);
		}
	}

	private TripleStore seededStore() throws Exception {
		TripleStore store = new TripleStore(directory.toFile(), new LmdbStoreConfig().setForceSync(true), null);
		try {
			store.startTransaction();
			store.storeTriple(10, 20, 30, 0, true);
			store.storeTriple(10, 20, 31, 7, true);
			store.storeTriple(11, 20, 30, 7, true);
			store.storeTriple(12, 21, 32, 7, true);
			store.storeTriple(13, 20, 30, 7, false);
			store.commit();
			return store;
		} catch (Throwable failure) {
			store.close();
			throw failure;
		}
	}
}
